#!/bin/zsh
# make_demo.sh : builds a test reference edit (6 shots with real cuts, a white flash, a dip to black, camera
# moves and a 120 BPM kick) plus 4 test photos, so you can try the remix before using real material.
# Writes demo-ref.mp4 and demo-photos/ here. Everything is generated by ffmpeg; nothing is downloaded.
set -e
cd ${0:A:h}
mkdir -p demo-tmp demo-photos
S=1080x1920
seg() { ffmpeg -loglevel error -y -f lavfi -i "$1" -t $2 -vf "$3,format=yuv420p,fps=30" -c:v libx264 -crf 20 demo-tmp/$4.mp4; }
ffmpeg -loglevel error -y -f lavfi -i "mandelbrot=s=2600x2600:start_scale=0.6:start_x=-0.743:start_y=0.131" -frames:v 1 demo-tmp/m.png
ffmpeg -loglevel error -y -f lavfi -i "mandelbrot=s=2600x2600:start_scale=1.2:start_x=-0.16:start_y=1.04" -frames:v 1 demo-tmp/n.png
still() { ffmpeg -loglevel error -y -loop 1 -framerate 30 -i demo-tmp/$1.png -t $2 -vf "$3,format=yuv420p" -c:v libx264 -crf 20 demo-tmp/$4.mp4; }
still m 1.0 "zoompan=z='1+0.012*on':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=1080x1920:fps=30" 1
still n 1.0 "crop=1080:1920:x='200+t*900':y=300" 2
seg "color=white:s=${S}:r=30" 0.067 "null" 3a
seg "gradients=s=${S}:c0=0x2E6F73:c1=0xFFCC00:x0=100:y0=100:x1=900:y1=1800:speed=0.03:r=30" 1.43 "null" 3
seg "life=s=270x480:mold=10:r=30:ratio=0.5:death_color=#16302f:life_color=#c8a96a,scale=${S}:flags=neighbor" 1.0 "null" 4
seg "color=black:s=${S}:r=30" 0.13 "null" 5a
still n 1.87 "zoompan=z='1.5-0.006*on':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=1080x1920:fps=30" 5
still m 1.5 "crop=1080:1920:x=700:y='600-t*350'" 6
for f in 1 2 3a 3 4 5a 5 6; do print "file '$f.mp4'"; done > demo-tmp/list.txt
ffmpeg -loglevel error -y -f concat -safe 0 -i demo-tmp/list.txt -c copy demo-tmp/v.mp4
ffmpeg -loglevel error -y -i demo-tmp/v.mp4 -f lavfi -i "aevalsrc='0.9*sin(2*PI*(45+140*exp(-35*mod(t,0.5)))*t)*exp(-9*mod(t,0.5))':s=44100:d=8" \
  -shortest -c:v copy -c:a aac -b:a 160k demo-ref.mp4
for i in 1 2 3 4; do
  C=(0x0d4d4d:0xc8a96a 0xc8a96a:0xf6f1e7 0x16302f:0x2E6F73 0xf6f1e7:0x0d4d4d)
  ffmpeg -loglevel error -y -f lavfi -i "gradients=s=${S}:c0=${C[$i]%%:*}:c1=${C[$i]##*:}:n=2:x0=$((i*150)):y0=200:x1=900:y1=$((1500+i*80)):seed=$i" -frames:v 1 -q:v 3 demo-photos/photo$i.jpg
done
cp ../synced/img/logo.png demo-photos/product.png
rm -rf demo-tmp
print "demo-ref.mp4 + demo-photos/. Next: python3 analyze.py demo-ref.mp4"
